141   if (auto *ATy = dyn_cast<ArrayType>(this)) {
142     unsigned NumElements = ATy->getNumElements();
143     return NumElements == 0 || ATy->getElementType()->isEmptyTy();
144   }
145 
146   if (auto *STy = dyn_cast<StructType>(this)) {
